class Krag {
  constructor(promien) {
    this.promien = promien;
  }
  get pole() {
    return Math.PI * this.promien ** 2;
  }
}

const krag = new Krag(3);
console.log(krag.pole); // ok. 28.27

class KontoBankowe {
  constructor(saldo) {
    this._saldo = saldo;
  }
  get saldo() {
    return this._saldo;
  }
  set saldo(nowaWartosc) {
    if (nowaWartosc < 0) throw new Error("Saldo nie moze byc ujemne");
    this._saldo = nowaWartosc;
  }
}

const konto = new KontoBankowe(100);
try {
  konto.saldo = -50;
} catch (error) {
  console.log(error.message); // "Saldo nie moze byc ujemne"
}

class Prostokat2 {
  constructor(szerokosc, wysokosc) {
    this._szerokosc = szerokosc;
    this._wysokosc = wysokosc;
  }
  get szerokosc() {
    return this._szerokosc;
  }
  set szerokosc(nowaWartosc) {
    if (nowaWartosc <= 0) throw new Error("Szerokosc musi byc dodatnia");
    this._szerokosc = nowaWartosc;
  }
  get pole() {
    return this._szerokosc * this._wysokosc;
  }
}

const rect = new Prostokat2(10, 5);
console.log(rect.pole); // 50
rect.szerokosc = 20;
console.log(rect.pole); // 100

