class Temperatura {
  constructor(celsjusz) {
    this._celsjusz = celsjusz;
  }
  get fahrenheit() {
    return this._celsjusz * 9 / 5 + 32;
  }
  set fahrenheit(wartoscF) {
    this._celsjusz = (wartoscF - 32) * 5 / 9;
  }
}

const temperatura = new Temperatura(20);
console.log(temperatura.fahrenheit); // 68
temperatura.fahrenheit = 100;
console.log(temperatura._celsjusz.toFixed(2)); // "37.78"

class Produkt4 {
  constructor(nazwa, cenaWGroszach) {
    this.nazwa = nazwa;
    this.cenaWGroszach = cenaWGroszach;
  }
  get cenaWZlotych() {
    return this.cenaWGroszach / 100;
  }
  set cenaWZlotych(nowaCena) {
    this.cenaWGroszach = nowaCena * 100;
  }
}

const produkt = new Produkt4("Ksiazka", 4999);
console.log(produkt.cenaWZlotych); // 49.99
produkt.cenaWZlotych = 39.99;
console.log(produkt.cenaWGroszach); // 3999

// Gdyby getter/setter mial DOKLADNIE ta sama nazwe co pole, na ktorym
// operuje (np. get szerokosc() { return this.szerokosc; }), powstalby
// nieskonczony cykl:
class ZlyProstokat {
  constructor(szerokosc) {
    this.szerokosc = szerokosc; // to wywoluje SETTER szerokosc, nie zwykle przypisanie!
  }
  get szerokosc() {
    return this.szerokosc; // wywoluje SAM SIEBIE (getter) w nieskonczonosc
  }
  set szerokosc(wartosc) {
    this.szerokosc = wartosc; // wywoluje SAM SIEBIE (setter) w nieskonczonosc
  }
}

